 const pool=["Аня","Оля","Маша","Лена"],count=d===0?3:4,context=g6RandomFrom(["higher","earlier","left"]);for(let guard=0;guard<80;guard++){const names=sh(pool).slice(0,count),hidden=sh(names),conditions=[];for(let i=0;i<hidden.length-1;i++)conditions.push({before:hidden[i],after:hidden[i+1]});const solutions=g3LogicOrderSolutions(names,conditions);if(solutions.length!==1)continue;const askIndex=d===2&&Math.random()<.35?1:0,answer=hidden[askIndex],conditionText=conditions.map(c=>context==="higher"?`${c.before} выше ${c.after}.`:context==="earlier"?`${c.before} пришла раньше ${c.after}.`:`${c.before} стоит левее ${c.after}.`).join("<br>"),question=context==="higher"?(askIndex===0?"Кто самая высокая?":"Кто занимает второе место по высоте?"):context==="earlier"?(askIndex===0?"Кто пришёл первым?":"Кто пришёл вторым?"):(askIndex===0?"Кто стоит левее всех?":"Кто стоит вторым слева?"),ex=`Единственный порядок: <b>${hidden.join(" → ")}</b>. Поэтому ответ: <b>${answer}</b>.`;return g3ChoiceQuestion(`${conditionText}<br><b>${question}</b>`,answer,names.map(n=>({key:n,label:n})),ex,`g3:algorithms_logic:${d}:logic:${context}:${conditions.map(c=>c.before+">"+c.after).join("|")}:q${askIndex}`,{variant:"logic",logicModel:{names,conditions,context,askIndex},hiddenSolution:hidden,solutionsCount:solutions.length,answer})}
 throw new Error("Не удалось создать однозначную логическую задачу");
}
function g3AlgorithmsLogicQuestion(d){const family=g6RandomFrom(["algorithm","sequence","logic"]);return family==="algorithm"?g3AlgorithmQuestion(d):family==="sequence"?g3SequenceQuestion
